class Node:
    def __init__(self, count=0):
        self.count = count
        self.keys = set()
        self.prev = None
        self.next = None

class AllOne:
    def __init__(self):
        self.head = Node()
        self.tail = Node()
        self.head.next = self.tail
        self.tail.prev = self.head
        self.key_node = {}

    def _insert_after(self, prev_node, count):
        node = Node(count)
        node.prev = prev_node
        node.next = prev_node.next
        prev_node.next.prev = node
        prev_node.next = node
        return node

    def _remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def inc(self, key: str) -> None:
        if key in self.key_node:
            node = self.key_node[key]
            new_count = node.count + 1
            if node.next.count != new_count:
                new_node = self._insert_after(node, new_count)
            else:
                new_node = node.next
            new_node.keys.add(key)
            self.key_node[key] = new_node
            node.keys.remove(key)
            if not node.keys:
                self._remove(node)
        else:
            if self.head.next.count != 1:
                new_node = self._insert_after(self.head, 1)
            else:
                new_node = self.head.next
            new_node.keys.add(key)
            self.key_node[key] = new_node

    def dec(self, key: str) -> None:
        node = self.key_node[key]
        new_count = node.count - 1
        if new_count == 0:
            del self.key_node[key]
        else:
            if node.prev.count != new_count:
                new_node = self._insert_after(node.prev, new_count)
            else:
                new_node = node.prev
            new_node.keys.add(key)
            self.key_node[key] = new_node
        node.keys.remove(key)
        if not node.keys:
            self._remove(node)

    def getMaxKey(self) -> str:
        if self.tail.prev == self.head:
            return ""
        return next(iter(self.tail.prev.keys))

    def getMinKey(self) -> str:
        if self.head.next == self.tail:
            return ""
        return next(iter(self.head.next.keys))

